appearances.css:
:host{font-size:9px}
.app{display:flex;flex-wrap:wrap;gap:4px;align-items:flex-start;padding:6px;border-radius:0}
.app>*{flex:1 1 100%;min-width:0}
.row{display:flex;flex-wrap:wrap;gap:3px 4px;align-items:center;margin:0}
.control span{font-size:7.5px;line-height:1.1;letter-spacing:-.02em}
select,button{font-size:9px;padding:3px 2px;border-radius:3px}
select{appearance:none;-webkit-appearance:none;text-overflow:ellipsis;padding:3px 4px}
.app>.row:nth-child(1){order:0;border:1px solid var(--line);border-radius:3px;padding:3px 4px 4px}
.app>.row:nth-child(1) .control{flex:1 1 100%;padding:0;border:0;gap:1px;flex-direction:row;align-items:center}
.app>.row:nth-child(1) .control span{font-size:8px;flex:0 0 auto;margin-right:4px}
.app>.row:nth-child(1) select{flex:1 1 auto}
.app>.row:nth-child(2){order:20;flex:1 1 170px;gap:3px 4px;border:1px solid var(--line);border-radius:3px;padding:3px 4px}
.app>.row:nth-child(2) button{flex:1 1 auto;padding:3px 4px}
.sec{flex:1 1 auto;border:1px solid var(--line);border-radius:3px;padding:3px 4px 4px;margin:0}
.sec h3{margin:0 0 2px;font-size:8px;letter-spacing:.14em;text-transform:uppercase;font-weight:600}
.sec .grid{display:flex;flex-wrap:wrap;gap:3px 0;justify-content:space-around}
.sec[data-lane=oscillator]{order:1}.sec[data-lane=output]{order:2}.sec[data-lane=filter]{order:3}.sec[data-lane=amp]{order:4}.sec[data-lane=chorus]{order:5}.sec[data-lane=modulation]{order:6}
.control:has(.kn){display:grid;grid-template-columns:100%;justify-items:center;align-content:start;gap:0;padding:0;border:0;flex:0 0 50px}
.control:has(.kn) span{order:3;text-align:center;max-width:100%}
.control:has(.kn) output{order:2;font-size:8px;line-height:1.2;text-align:center}
.control:has(.kn) .kn{order:1;width:26px!important;height:26px!important;justify-self:center!important}
.control .kn svg{width:100%;height:100%}
.sec .control:has(select){flex:0 0 56px;padding:0;border:0;gap:1px}
.app>.row:nth-child(2) .control:has(.kn){flex:0 0 50px}
.app>h3{order:21;margin:0;font-size:8px;letter-spacing:.14em;text-transform:uppercase;flex:0 0 100%}
canvas{order:22;height:30px}
p{order:23;margin:0;font-size:8px;line-height:1.2}
